class Solution {
public:
    int convertTime(string current, string correct) {
        auto to_min = [](const string& s) {
            int h = stoi(s.substr(0, 2));
            int m = stoi(s.substr(3, 2));
            return h * 60 + m;
        };
        int diff = to_min(correct) - to_min(current);
        int ans = 0;
        int steps[] = {60, 15, 5, 1};
        for (int s : steps) {
            ans += diff / s;
            diff %= s;
        }
        return ans;
    }
};

class Solution {
    public int convertTime(String current, String correct) {
        int curM = Integer.parseInt(current.substring(0, 2)) * 60 + Integer.parseInt(current.substring(3, 5));
        int corM = Integer.parseInt(correct.substring(0, 2)) * 60 + Integer.parseInt(correct.substring(3, 5));
        int diff = corM - curM;
        int ans = 0;
        int[] steps = {60, 15, 5, 1};
        for (int s : steps) {
            ans += diff / s;
            diff %= s;
        }
        return ans;
    }
}

/**
 * @param {string} current
 * @param {string} correct
 * @return {number}
 */
var convertTime = function(current, correct) {
    const toMin = (s) => {
        const [h, m] = s.split(':').map(Number);
        return h * 60 + m;
    };
    let diff = toMin(correct) - toMin(current);
    let ans = 0;
    const steps = [60, 15, 5, 1];
    for (const s of steps) {
        ans += Math.floor(diff / s);
        diff %= s;
    }
    return ans;
};
